CREATE TABLE pay_periods (
 id UUID PRIMARY KEY, period_code VARCHAR(50) NOT NULL UNIQUE, start_date DATE NOT NULL, end_date DATE NOT NULL, payment_date DATE, status VARCHAR(30) NOT NULL DEFAULT 'OPEN', created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CONSTRAINT chk_pay_periods_dates CHECK (start_date <= end_date));
CREATE TABLE driver_pay_policies (
 id UUID PRIMARY KEY, policy_code VARCHAR(80) NOT NULL, name VARCHAR(200) NOT NULL, driver_id UUID, pay_method VARCHAR(40) NOT NULL, per_mile_rate NUMERIC(19,6), per_load_rate NUMERIC(19,4), hourly_rate NUMERIC(19,6), daily_rate NUMERIC(19,4), flat_rate NUMERIC(19,4), revenue_percentage NUMERIC(9,6), mileage_basis VARCHAR(40), revenue_basis VARCHAR(50), detention_rate NUMERIC(19,6), detention_free_minutes INTEGER, detention_block_minutes INTEGER, layover_rate NUMERIC(19,4), stop_pay_rate NUMERIC(19,4), currency VARCHAR(3) NOT NULL, effective_from DATE NOT NULL, effective_to DATE, policy_version INTEGER NOT NULL DEFAULT 1, active BOOLEAN NOT NULL DEFAULT TRUE, version INT8 NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CONSTRAINT uq_driver_pay_policies_version UNIQUE(policy_code, policy_version), CONSTRAINT fk_driver_pay_policies_driver FOREIGN KEY(driver_id) REFERENCES employees(id) ON DELETE SET NULL, CONSTRAINT chk_driver_pay_policies_percentage CHECK(revenue_percentage IS NULL OR revenue_percentage BETWEEN 0 AND 1), CONSTRAINT chk_driver_pay_policies_dates CHECK(effective_to IS NULL OR effective_to >= effective_from));
CREATE TABLE settlements (
 id UUID PRIMARY KEY, settlement_number VARCHAR(60) NOT NULL UNIQUE, driver_id UUID NOT NULL, pay_period_id UUID NOT NULL, settlement_type VARCHAR(20) NOT NULL DEFAULT 'ORIGINAL', parent_settlement_id UUID, sequence_number INTEGER NOT NULL DEFAULT 0, pay_policy_id UUID NOT NULL, pay_policy_version INTEGER NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'DRAFT', currency VARCHAR(3) NOT NULL, mileage_pay NUMERIC(19,4) NOT NULL DEFAULT 0, load_pay NUMERIC(19,4) NOT NULL DEFAULT 0, percentage_pay NUMERIC(19,4) NOT NULL DEFAULT 0, hourly_pay NUMERIC(19,4) NOT NULL DEFAULT 0, accessorial_pay NUMERIC(19,4) NOT NULL DEFAULT 0, bonus_amount NUMERIC(19,4) NOT NULL DEFAULT 0, reimbursement_amount NUMERIC(19,4) NOT NULL DEFAULT 0, deduction_amount NUMERIC(19,4) NOT NULL DEFAULT 0, gross_earnings NUMERIC(19,4) NOT NULL DEFAULT 0, settlement_net NUMERIC(19,4) NOT NULL DEFAULT 0, eligible_miles NUMERIC(19,3), loaded_miles NUMERIC(19,3), empty_miles NUMERIC(19,3), eligible_hours NUMERIC(19,3), calculation_snapshot_id UUID NOT NULL, calculated_at TIMESTAMPTZ, reviewed_at TIMESTAMPTZ, reviewed_by UUID, approved_at TIMESTAMPTZ, approved_by UUID, locked_at TIMESTAMPTZ, locked_by UUID, paid_at TIMESTAMPTZ, version INT8 NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CONSTRAINT fk_settlements_driver FOREIGN KEY(driver_id) REFERENCES employees(id), CONSTRAINT fk_settlements_period FOREIGN KEY(pay_period_id) REFERENCES pay_periods(id), CONSTRAINT fk_settlements_policy FOREIGN KEY(pay_policy_id) REFERENCES driver_pay_policies(id), CONSTRAINT fk_settlements_parent FOREIGN KEY(parent_settlement_id) REFERENCES settlements(id), CONSTRAINT fk_settlements_snapshot FOREIGN KEY(calculation_snapshot_id) REFERENCES calculation_snapshots(id), CONSTRAINT chk_settlements_type CHECK(settlement_type IN ('ORIGINAL','ADJUSTMENT','REVERSAL')));
CREATE UNIQUE INDEX uq_settlements_original_driver_period ON settlements(driver_id,pay_period_id) WHERE settlement_type='ORIGINAL';
CREATE UNIQUE INDEX uq_settlements_parent_sequence ON settlements(parent_settlement_id,sequence_number) WHERE parent_settlement_id IS NOT NULL;
CREATE TABLE settlement_lines (
 id UUID PRIMARY KEY, settlement_id UUID NOT NULL, line_type VARCHAR(50) NOT NULL, load_id UUID, trip_id UUID, accessorial_charge_id UUID, expense_id UUID, description VARCHAR(300) NOT NULL, quantity NUMERIC(19,6), unit VARCHAR(30), rate NUMERIC(19,6), amount NUMERIC(19,4) NOT NULL, currency VARCHAR(3) NOT NULL, taxable BOOLEAN DEFAULT TRUE, line_class VARCHAR(30) NOT NULL, source_type VARCHAR(40), source_id UUID, calculation_snapshot_id UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CONSTRAINT fk_settlement_lines_settlement FOREIGN KEY(settlement_id) REFERENCES settlements(id) ON DELETE RESTRICT, CONSTRAINT fk_settlement_lines_load FOREIGN KEY(load_id) REFERENCES loads(id) ON DELETE SET NULL, CONSTRAINT fk_settlement_lines_trip FOREIGN KEY(trip_id) REFERENCES trips(id) ON DELETE SET NULL, CONSTRAINT fk_settlement_lines_accessorial FOREIGN KEY(accessorial_charge_id) REFERENCES accessorial_charges(id) ON DELETE SET NULL, CONSTRAINT fk_settlement_lines_expense FOREIGN KEY(expense_id) REFERENCES expenses(id) ON DELETE SET NULL, CONSTRAINT fk_settlement_lines_snapshot FOREIGN KEY(calculation_snapshot_id) REFERENCES calculation_snapshots(id) ON DELETE SET NULL, CONSTRAINT chk_settlement_line_class CHECK(line_class IN ('EARNING','DEDUCTION','REIMBURSEMENT')));
CREATE INDEX ix_settlement_lines_settlement ON settlement_lines(settlement_id);
